def initialize_organization(apps, schema_editor):
    apps.get_model('core','Organization').objects.create(name='ООО «Организация Бета»',timezone='Asia/Yakutsk')


def split_known_addresses(apps,schema_editor):
    import re
    for building in apps.get_model('core','Building').objects.all():
        match = re.match(r'^(.*?),?\s+(\d+[\w/\-]*)$',building.address.strip())
        if match:
            building.street = match.group(1).rstrip(', ')
            building.house = match.group(2)
            building.save(update_fields=['street','house'])


